import{_ as a,o as e,c as s,ai as i}from"./chunks/framework.Ba-VnP44.js";const c=JSON.parse('{"title":"提示词库 · 六类","description":"","frontmatter":{},"headers":[],"relativePath":"ai/prompts/index.md","filePath":"ai/prompts/index.md"}'),r={name:"ai/prompts/index.md"};function n(d,t,l,p,h,o){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="提示词库-·-六类" tabindex="-1">提示词库 · 六类 <a class="header-anchor" href="#提示词库-·-六类" aria-label="Permalink to “提示词库 · 六类”">​</a></h1><blockquote><p>我自己常用的一套提示词，按用途分六类、共 78 条。每条都能直接复制，占位符用【】标出。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>我每次必填的东西</th><th>条数</th><th>入口</th></tr></thead><tbody><tr><td>编程开发</td><td>技术栈、现有约束、报错原文</td><td>29</td><td><a href="/my-vitepress-site/ai/prompts/coding.html">编程开发</a></td></tr><tr><td>写作与表达</td><td>读者是谁、篇幅、语气</td><td>12</td><td><a href="/my-vitepress-site/ai/prompts/writing.html">写作与表达</a></td></tr><tr><td>分析与决策</td><td>对比维度、权重、证据来源</td><td>10</td><td><a href="/my-vitepress-site/ai/prompts/analysis.html">分析与决策</a></td></tr><tr><td>学习与理解</td><td>我的现有水平、目标深度</td><td>9</td><td><a href="/my-vitepress-site/ai/prompts/learning.html">学习与理解</a></td></tr><tr><td>创意与内容</td><td>受众、平台、我的素材</td><td>10</td><td><a href="/my-vitepress-site/ai/prompts/creation.html">创意与内容</a></td></tr><tr><td>角色与系统提示词</td><td>职责边界、输出结构、拒答条件</td><td>8</td><td><a href="/my-vitepress-site/ai/prompts/agent.html">角色与系统提示词</a></td></tr></tbody></table><h2 id="通用底座" tabindex="-1">通用底座 <a class="header-anchor" href="#通用底座" aria-label="Permalink to “通用底座”">​</a></h2><p>所有模板都是这一个骨架的变形，记住它就够用：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>背景：我是【谁】，在做【什么事】，用【工具/技术栈】。</span></span>
<span class="line"><span>现状：现在是什么样，有什么限制，贴关键素材（代码 / 数据 / 原文 / 报错）。</span></span>
<span class="line"><span>目标：一句话，可验证（“P95 降到 300ms”“800 字以内”“给 8 个选题”）。</span></span>
<span class="line"><span>约束：不能【…】；必须【…】；风格/口径【…】。</span></span>
<span class="line"><span>输出：要方案还是要成品，要表格还是清单，要不要给理由。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>三条尾巴，按需挂：</p><ul><li>开头：“先复述你对这个任务的理解，确认无误再开始。”</li><li>结尾：“对照上面的约束逐条自检，列出哪些满足、哪些没满足。”</li><li>兜底：“不确定的地方标出来，不要编。”</li></ul><h2 id="用的时候" tabindex="-1">用的时候 <a class="header-anchor" href="#用的时候" aria-label="Permalink to “用的时候”">​</a></h2><ul><li>先替换占位符，再删掉用不上的约束——约束太多会互相打架。</li><li>能贴代码就贴代码，能贴报错原文就不要转述。</li><li>一次只问一件事。</li><li>用完把临时补的约束回写进模板。</li></ul><hr><p>延伸：<a href="/my-vitepress-site/ai/productivity/ai-coding-workflow.html">AI 辅助编程工作流</a> · <a href="/my-vitepress-site/ai/productivity/tool-selection.html">AI 工具与选型</a></p>`,12)])])}const b=a(r,[["render",n]]);export{c as __pageData,b as default};
